sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float scale;
uniform float2 offset;
uniform float mirror;
half4 main(float2 coord) {
    float2 t = (coord / size - offset) / max(scale, 0.02);
    float2 f = fract(t);
    if (mirror > 0.5) f = mix(f, 1 - f, mod(floor(t), 2));
    return image.eval(f * size);
}
